_sage_const_120 = Integer(120); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_20001 = Integer(20001); _sage_const_0 = Integer(0); _sage_const_12 = Integer(12); _sage_const_20 = Integer(20); _sage_const_14 = Integer(14); _sage_const_6 = Integer(6); _sage_const_11 = Integer(11); _sage_const_18 = Integer(18); _sage_const_3 = Integer(3); _sage_const_5 = Integer(5); _sage_const_7 = Integer(7); _sage_const_9 = Integer(9)# Fit polynomial approximations for sqrt(x) on variance intervals.
