R = RealField(_sage_const_120 )


def fit_cheb_interpolant(lo, hi, degree):
    """Return power-basis coefficients for a Chebyshev-node interpolant."""
    point_count = degree + _sage_const_1 
    xs = []
    ys = []
    pi_value = R.pi()

    for idx in range(point_count):
        node = R(cos((_sage_const_2  * idx + _sage_const_1 ) * pi_value / (_sage_const_2  * point_count)))
        x_value = (R(lo) + R(hi)) / _sage_const_2  + (R(hi) - R(lo)) / _sage_const_2  * node
        xs.append(x_value)
        ys.append(sqrt(x_value))

    system = matrix(
        R,
        [[x_value**power for power in range(point_count)] for x_value in xs],
    )
    return list(system.solve_right(vector(R, ys)))


def max_grid_error(coeffs, lo, hi, sample_count=_sage_const_20001 ):
    """Estimate max absolute approximation error on a dense grid."""
    max_error = R(_sage_const_0 )
    max_x = R(lo)

    for idx in range(sample_count):
        x_value = R(lo) + (R(hi) - R(lo)) * R(idx) / R(sample_count - _sage_const_1 )
        approx = sum(
            coeff * x_value**power for power, coeff in enumerate(coeffs)
        )
        error = abs(approx - sqrt(x_value))
        if error > max_error:
            max_error = error
            max_x = x_value

    return max_error, max_x


def print_fit(lo, hi, degree):
    coeffs = fit_cheb_interpolant(lo, hi, degree)
    max_error, max_x = max_grid_error(coeffs, lo, hi)

    print("interval:", n(R(lo), digits=_sage_const_12 ), n(R(hi), digits=_sage_const_12 ))
    print("degree:", degree)
    print("power basis coefficients:")
    for idx, coeff in enumerate(coeffs):
        print(f"  a{idx} = {n(coeff, digits=_sage_const_20 )}")
    print("max grid error:", n(max_error, digits=_sage_const_14 ))
    print("max error at x:", n(max_x, digits=_sage_const_14 ))
    print()


def print_rust_coeff_array(lo, hi, degree):
    coeffs = fit_cheb_interpolant(lo, hi, degree)
    max_error, max_x = max_grid_error(coeffs, lo, hi)

    print(
        "Rust coefficients for sqrt(x), interval ["
        + str(n(R(lo), digits=_sage_const_12 ))
        + ", "
        + str(n(R(hi), digits=_sage_const_12 ))
        + "], degree "
        + str(degree)
    )
    print("const SQRT_COEFFS: [f64; " + str(degree + _sage_const_1 ) + "] = [")
    for coeff in coeffs:
        print("    " + str(n(coeff, digits=_sage_const_20 )) + ",")
    print("];")
    print("max grid error:", n(max_error, digits=_sage_const_14 ))
    print("max error at x:", n(max_x, digits=_sage_const_14 ))
    print()


def print_degree_sweep(lo, hi, degrees):
    print("interval:", n(R(lo), digits=_sage_const_12 ), n(R(hi), digits=_sage_const_12 ))
    print("degree sweep:")
    print("  degree | horner_muls | balanced_depth_est | max_grid_error | at_x")
    for degree in degrees:
        coeffs = fit_cheb_interpolant(lo, hi, degree)
        max_error, max_x = max_grid_error(coeffs, lo, hi)
        if degree <= _sage_const_1 :
            balanced_depth = degree
        else:
            balanced_depth = ceil(log(R(degree), R(_sage_const_2 )))
        print(
            "  "
            + str(degree).rjust(_sage_const_6 )
            + " | "
            + str(degree).rjust(_sage_const_11 )
            + " | "
            + str(balanced_depth).rjust(_sage_const_18 )
            + " | "
            + str(n(max_error, digits=_sage_const_12 )).rjust(_sage_const_14 )
            + " | "
            + str(n(max_x, digits=_sage_const_12 ))
        )
    print()


